import re
for f in ('LAT.txt','LEW_1910.txt'):
    t=open(f,encoding='utf-8',errors='replace').read()
    print('######',f, len(t))
    for pat in [r'\net,? *(conj|adv)', r'\nuanus', r'\nvanus', r'\nuastus', r'\nvastus', r'uaco', r'\nvaco']:
        m=re.search(pat,t)
        if m: print(pat,'->', t[m.start():m.start()+450].replace('\n',' '))
        else: print(pat,'-> none')
EOF

